import { createContext, useContext, useEffect, useRef, useState } from "react";
import { Switch } from "@/components/ui/switch";
import { API_BASE } from "@/lib/config";
import type { Message } from "@/gotypes";

export const GAMA_PERFORMANCE = 1;
export const GAMA_EXPORT = 2;
export const GAMA_MONITOR = 4;
export const GamaContext = createContext(GAMA_PERFORMANCE);

const modules = [
  { bit: GAMA_PERFORMANCE, title: "Métricas por resposta", description: "Registra e exibe desempenho da inferência. Dados anteriores permanecem salvos." },
  { bit: GAMA_EXPORT, title: "Exportação de conversa", description: "Copia mensagens visíveis em Markdown ou JSON, sem anexos ou raciocínio interno." },
  { bit: GAMA_MONITOR, title: "Modelos em memória", description: "Consulta sob demanda; sem monitoramento contínuo ou liberação automática." },
];

export function GamaModulesCard({ flags, onChange }: { flags: number; onChange: (flags: number) => void }) {
  return (
    <section aria-label="Gama · Recursos adicionais" className="rounded-xl bg-white dark:bg-neutral-800 p-4 space-y-4">
      <header>
        <h2 className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">Gama · Recursos adicionais</h2>
        <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1">Personalizações opcionais, independentes das configurações nativas.</p>
      </header>
      {modules.map(m => (
        <div key={m.bit} className="flex items-start justify-between gap-4">
          <div className="flex-1">
            <div className="text-sm font-medium">{m.title}</div>
            <p className="text-xs text-neutral-500 dark:text-neutral-400">{m.description}</p>
          </div>
          <Switch aria-label={m.title} checked={(flags & m.bit) !== 0} onChange={checked => onChange(checked ? flags | m.bit : flags & ~m.bit)} />
        </div>
      ))}
    </section>
  );
}

export function visibleMessages(messages: Message[]) {
  return messages.filter(m => (m.role === "user" || m.role === "assistant") && m.content?.trim() && !m.stream)
    .map(m => ({ role: m.role, ...(m.model ? { model: m.model } : {}), content: m.content }));
}
export function formatConversation(title: string, messages: Message[], format: "md" | "json") {
  const rows = visibleMessages(messages);
  if (format === "json") return JSON.stringify({ title, messages: rows }, null, 2);
  return ["# " + title.replace(/[\r\n]/g, " "), ...rows.map(m =>
    "## " + (m.role === "user" ? "Você" : "Assistente" + ("model" in m ? " · " + String(m.model).replace(/[\r\n]/g, " ") : "")) + "\n\n" + m.content
  )].join("\n\n");
}

type Resident = { name: string; model: string; size: number; size_vram: number; context_length: number };
function ResidentMonitor() {
  const [open, setOpen] = useState(false);
  const [models, setModels] = useState<Resident[] | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const request = useRef<AbortController | null>(null);
  useEffect(() => () => request.current?.abort(), []);
  const refresh = async () => {
    request.current?.abort();
    const controller = new AbortController();
    request.current = controller;
    setLoading(true);
    setError("");
    setModels(null);
    try {
      const response = await fetch(API_BASE + "/api/v1/gama/resident-models", { signal: controller.signal, cache: "no-store" });
      if (!response.ok) throw new Error("Não foi possível consultar os modelos.");
      const result = await response.json();
      if (!controller.signal.aborted) setModels(Array.isArray(result?.models) ? result.models : []);
    } catch {
      if (!controller.signal.aborted) setError("Falha ao consultar o servidor local.");
    } finally {
      if (!controller.signal.aborted) setLoading(false);
    }
  };
  return (
    <div className="text-xs">
      <button type="button" className="underline underline-offset-2" aria-expanded={open} onClick={() => {
        if (open) { request.current?.abort(); setOpen(false); setLoading(false); setModels(null); setError(""); }
        else { setOpen(true); void refresh(); }
      }}>Modelos em memória</button>
      {open && <div className="mt-2 rounded-lg border border-neutral-200 dark:border-neutral-700 p-3 space-y-2">
        <div className="flex justify-between gap-2"><strong>Snapshot local</strong><button type="button" disabled={loading} onClick={() => void refresh()}>Atualizar</button></div>
        {loading && <p role="status">Consultando...</p>}
        {error && <p role="alert">{error}</p>}
        {models?.length === 0 && <p>Nenhum modelo residente.</p>}
        {models?.map(m => <div key={m.model || m.name} className="flex flex-wrap justify-between gap-2"><span>{m.name || m.model}</span><span>{(m.size_vram / 1e9).toFixed(2)} GB VRAM / {(m.size / 1e9).toFixed(2)} GB alocados · {m.context_length || "—"} ctx</span></div>)}
        <p className="text-neutral-500">Alocação informada pelo servidor, não utilização instantânea.</p>
      </div>}
    </div>
  );
}

function ExportControls({ title, messages, busy }: { title: string; messages: Message[]; busy: boolean }) {
  const [status, setStatus] = useState("");
  const copy = async (format: "md" | "json") => {
    try {
      await navigator.clipboard.writeText(formatConversation(title, messages, format));
      setStatus(format === "md" ? "Markdown copiado." : "JSON copiado.");
    } catch { setStatus("Não foi possível copiar."); }
  };
  return <div className="flex flex-wrap gap-3 items-center text-xs">
    <button type="button" disabled={busy || !messages.length} onClick={() => void copy("md")}>Copiar Markdown</button>
    <button type="button" disabled={busy || !messages.length} onClick={() => void copy("json")}>Copiar JSON</button>
    <span role="status">{status}</span>
  </div>;
}

export function GamaChatTools(props: { title: string; messages: Message[]; busy: boolean }) {
  const flags = useContext(GamaContext);
  if (!(flags & (GAMA_EXPORT | GAMA_MONITOR))) return null;
  return <div className="mx-auto max-w-3xl px-4 pb-2 flex flex-col gap-2 text-neutral-500 dark:text-neutral-400">
    {(flags & GAMA_EXPORT) !== 0 && <ExportControls {...props} />}
    {(flags & GAMA_MONITOR) !== 0 && <ResidentMonitor />}
  </div>;
}

