package store

import (
 "path/filepath"
 "testing"
)

func TestGamaModulesPersistence(t *testing.T) {
 path := filepath.Join(t.TempDir(), "gama.db")
 db, err := newDatabase(path)
 if err != nil { t.Fatal(err) }
 settings, err := db.getSettings()
 if err != nil { t.Fatal(err) }
 if settings.GamaModules != GamaPerformance { t.Fatalf("unexpected default: %d", settings.GamaModules) }
 settings.GamaModules = GamaExport | GamaMonitor
 if err := db.setSettings(settings); err != nil { t.Fatal(err) }
 if err := db.Close(); err != nil { t.Fatal(err) }
 db, err = newDatabase(path)
 if err != nil { t.Fatal(err) }
 defer db.Close()
 got, err := db.getSettings()
 if err != nil { t.Fatal(err) }
 if got.GamaModules != GamaExport | GamaMonitor { t.Fatalf("flags not preserved: %d", got.GamaModules) }
 got.GamaModules = 0
 if err := db.setSettings(got); err != nil { t.Fatal(err) }
 got, err = db.getSettings()
 if err != nil || got.GamaModules != 0 { t.Fatalf("off not persisted: %+v %v", got, err) }
}

