import { describe, it, expect } from "vitest";
import { Message } from "@/gotypes";
import { formatConversation } from "./GamaModules";
describe("Gama conversation export", () => {
  it("exports visible completed text only, preserving model identity", () => {
    const messages = [
      new Message({role:"user",content:"Pergunta",attachments:[{filename:"private.txt",data:[1,2]}]}),
      new Message({role:"assistant",content:"Resposta",model:"qwen",thinking:"private reasoning"}),
      new Message({role:"tool",content:"private tool"}),
      new Message({role:"assistant",content:"partial",stream:true}),
    ];
    const data = JSON.parse(formatConversation("Chat", messages, "json"));
    expect(data.messages).toEqual([{role:"user",content:"Pergunta"},{role:"assistant",model:"qwen",content:"Resposta"}]);
    const md = formatConversation("Chat", messages, "md");
    expect(md).toContain("## Assistente · qwen");
    expect(md).not.toContain("private");
    expect(md).not.toContain("partial");
  });
});
